// domain/work/thread.ts
export interface AskReaders extends TurnReaders {
  /** The agent that wrote this comment, when the machinery tagged it with one. */
  authoringAgent: (body: string) => string;
}

export type AskAuthor = { kind: "person" } | { kind: "agent"; agent: string } | { kind: "body" };

export interface NewestAsk {
  agent: string;          // the agent the ask names
  author: AskAuthor;      // who made it
}

export function newestAsk(body: string, comments: readonly ThreadEntry[], readers: AskReaders): NewestAsk | undefined {
  const { comments: kept } = shapedThread(comments, readers);
  for (let i = kept.length - 1; i >= 0; i -= 1) {
    const entry = kept[i]!;
    const agent = readers.requestedAgent(entry.body);
    if (agent === "") continue;
    if (readers.isDispatchMarker(entry.body)) continue; // a take-up, not an ask
    const authorAgent = readers.authoringAgent(entry.body);
    return {
      agent,
      author: entry.isHuman ? { kind: "person" } : authorAgent ? { kind: "agent", agent: authorAgent } : { kind: "body" },
