/**
 * Who made an ask, as `latestAsk` reports it.
 *
 * A person's command and an agent's hand-off directive are the two asks somebody
 * stands behind: a push that answers either can be judged by its author. The
 * machinery's comments are the third kind of request in a thread -- the dispatch
 * marker -- and that one is a take-up rather than an ask, which is why it is not
 * an author here.
 */
export type AskAuthor = { kind: "person" } | { kind: "agent"; agent: string };

/** The newest ask in a thread that a push could answer, as `latestAsk` returns it. */
export interface LatestAsk {
  /** The agent the ask names. */
  agent: string;
  /** Who made it -- and who therefore judges the answer to it. */
  author: AskAuthor;
  /**
   * When the ask was written, as the entry carried it. Empty when the entry had no
   * time, which a caller must treat as unreadable rather than as "very old".
   */
  at: string;
}

/**
 * How to read the agent a machinery comment was written by.
 *
 * Extends `TurnReaders` because the question is adjacent to the turn's but not of
 * it: the runner tags its result comment with the agent that produced it, and the
 * wire format is the caller's (`adapters/github/tags.ts`), not this module's.
 */
export interface AskReaders extends TurnReaders {
  /** The agent the machinery tagged this comment as written by, or "" when it did not. */
  authoringAgent: (body: string) => string;
}

/**
 * The newest ask a person or an agent made in a thread, with who made it and when.
 *
 * ## Why the dispatch markers are not asks
 *
 * `latestRequestedAgent` reads them as requests, because for whose-turn-they-are
 * they are: a marker is the node being handed to an agent. But the marker is the
 * machinery TAKING UP a request, not one it is making -- the ask it took up sits in
 * the comment before it. The question here is "who asked, so their answer can be
 * returned to them", and a marker has no author to return to. So this walk skips
 * markers, and the ask underneath -- the reviewer's directive, the person's
 * command -- is what it finds.
 *
 * ## Why the body is not an ask either
 *
 * The body's `/<agent>` line is the node's standing request: it asks for the work
 * to be done, and a push is part of that work, not an answer to it. Returning
 * control over it would hand the pull request back to its opener on every push,
 * which is the routing `latestRequestedAgent` already gets right by dispatching
 * the named agent. Only an ask that somebody COMPLETED a turn by making -- a
 * person's command, an agent's directive -- is one a push can answer.
 *
 * ## The one comment that stops the walk
