      for (const raw of body.split("\n")) {
        const line = raw.trim();
        if (line.startsWith("/")) return line.slice(1).split(/\s/)[0]!;
        if (line.startsWith("DISPATCH ")) return line.slice("DISPATCH ".length).split(/\s/)[0]!;
